                    best_t = t
            return step_toward(self_p, best_t)
        center = (w // 2 if w else sx, h // 2 if h else sy)
        return step_toward(self_p, center)

    resources = valid_targets(observation.get("resources")) or valid_targets(observation.get("resource_positions"))
    if resources:
